INSERT INTO @t VALUES (N'az', N'The numbers the bank works by. Finance rules apply right away. Loan rules apply only to new loans: a loan that is already signed keeps its own rate and penalties. Every change is written to the audit log.', N'Bankın işlədiyi rəqəmlər. Maliyyə qaydaları dərhal tətbiq olunur. Kredit qaydaları yalnız yeni kreditlərə aiddir: artıq imzalanmış kredit öz faizini və cərimələrini saxlayır. Hər dəyişiklik audit jurnalına yazılır.');
