INSERT INTO @t VALUES (N'az', N'The system watches transfers and sign-ins and raises an alert when something looks unusual. Nothing is blocked automatically: look at each alert, then mark it safe or freeze the account.', N'Sistem köçürmələrə və girişlərə baxır və qeyri-adi bir şey görəndə siqnal verir. Heç nə avtomatik bloklanmır: hər siqnala baxın, sonra təhlükəsiz kimi işarələyin və ya hesabı dondurun.');
INSERT INTO @t VALUES (N'ru', N'The system watches transfers and sign-ins and raises an alert when something looks unusual. Nothing is blocked automatically: look at each alert, then mark it safe or freeze the account.', N'Система следит за переводами и входами и подаёт сигнал, если что-то выглядит необычно. Автоматически ничего не блокируется: посмотрите каждый сигнал, затем отметьте его безопасным или заморозьте счёт.');
